// Text to speech with the browser's built-in Web Speech voices: voice, speed, pitch, word highlighting, pause/resume. Speech is generated by your device's own voices (some browsers use online voices – noted).
TOOLS.tts={live:true,noAdv:true,goLabel:()=>T.download,
 opts:()=>`<label>Text to read aloud<textarea id="tstext" rows="8">Welcome! This free text to speech tool reads anything you paste here out loud, using the voices already installed on your device. Change the voice, the speed and the pitch, then press play.</textarea></label>`+sel('tsvoice','Voice',[['','Loading voices…']])+`<div class="row2">${inp('tsrate','Speed','range','1','min="0.5" max="2" step="0.1"')}${inp('tspitch','Pitch','range','1','min="0.5" max="2" step="0.1"')}</div>`+chk('tsfilter','Only voices for my language',false),
 setup(){const el=document.createElement('div');el.innerHTML='<div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin:8px 0"><button type="button" class="btn big" id="tsplay">▶ Play</button><button type="button" class="btn ghost" id="tspause">⏸ Pause</button><button type="button" class="btn ghost" id="tsstop">⏹ Stop</button></div><div id="tsview" style="line-height:1.8;padding:12px;border:1px solid var(--bd,#ddd);border-radius:10px;max-height:300px;overflow:auto"></div><p class="hint" id="tsinfo"></p>';
  const S=window.speechSynthesis;if(!S){$('#tsinfo',el).textContent='Your browser does not support speech synthesis. Try Chrome, Edge, Safari or Firefox.';return el;}
  const fill=()=>{const vs=S.getVoices();const s=$('#tsvoice',work);if(!s||!vs.length)return;const lang=(navigator.language||'en').slice(0,2);const keep=s.value;const list=vb('tsfilter')?vs.filter(x=>x.lang.startsWith(lang)):vs;s.innerHTML=list.map(x=>`<option value="${esc(x.voiceURI)}">${esc(x.name)} (${esc(x.lang)})${x.localService?'':' · online'}</option>`).join('');const def=list.find(x=>x.voiceURI===keep)||list.find(x=>x.default&&x.lang.startsWith(lang))||list.find(x=>x.lang.startsWith(lang))||list[0];if(def)s.value=def.voiceURI;$('#tsinfo',work).textContent=`${vs.length} voices available on this device. Voices marked “online” are streamed by your browser vendor; all others run locally.`;};
  S.onvoiceschanged=fill;setTimeout(fill,50);setTimeout(()=>{$('#tsfilter',work).addEventListener('change',fill);});
  $('#tsplay',el).onclick=()=>{S.cancel();const t=v('tstext')||'';if(!t.trim())return;const u=new SpeechSynthesisUtterance(t);const vo=S.getVoices().find(x=>x.voiceURI===v('tsvoice'));if(vo){u.voice=vo;u.lang=vo.lang;}u.rate=+v('tsrate')||1;u.pitch=+v('tspitch')||1;
   const view=$('#tsview',work);u.onboundary=e=>{if(e.name&&e.name!=='word')return;const i=e.charIndex,len=e.charLength||((t.slice(i).match(/^\S+/)||[''])[0].length);view.innerHTML=esc(t.slice(0,i))+'<mark>'+esc(t.slice(i,i+len))+'</mark>'+esc(t.slice(i+len));view.querySelector('mark')?.scrollIntoView({block:'nearest'});};u.onend=()=>{view.textContent=t;$('#tsplay',work).textContent='▶ Play';};S.speak(u);$('#tsplay',work).textContent='🔁 Restart';};
  $('#tspause',el).onclick=()=>{if(S.paused){S.resume();$('#tspause',work).textContent='⏸ Pause';}else if(S.speaking){S.pause();$('#tspause',work).textContent='⏯ Resume';}};$('#tsstop',el).onclick=()=>{S.cancel();$('#tsplay',work).textContent='▶ Play';};return el;},
 run(){const t=v('tstext')||'';$('#tsview',work).textContent=t;if(!t.trim())throw Object.assign(new Error('Type or paste some text'),{soft:true});const w=(t.match(/\S+/g)||[]).length;const mins=w/(170*(+v('tsrate')||1));
  return {blob:new Blob([t],{type:'text/plain'}),name:'speech-text.txt',info:`${w} words · about ${mins<1?Math.max(1,Math.round(mins*60))+' s':mins.toFixed(1)+' min'} of speech`};}};
